import{z as i,x as n,o as A,c as s,q as B,j as t,D as a,d as r,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"贡献流程与收束","description":"","frontmatter":{"title":"贡献流程与收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fw-contribution-map.md","filePath":"llm/fw-contribution-map.md","lastUpdated":1791413859000}'),p={name:"llm/fw-contribution-map.md"};function d(m,E,C,D,_,h){const e=n("Mermaid");return A(),s("div",null,[E[2]||(E[2]=B('<h1 id="贡献流程与收束" tabindex="-1">贡献流程与收束 <a class="header-anchor" href="#贡献流程与收束" aria-label="Permalink to &quot;贡献流程与收束&quot;">​</a></h1><div class="epigraph"><p>读码的终点是改码被合入：走读给了你判断力，流程把判断力兑换成仓库里的提交。</p><footer>—— 据 vLLM、SGLang、llama.cpp 等仓库的贡献指南与开发者文档整理</footer></div><p><a href="/llm/fw-perf-regression">上一课</a>立了性能报数的协议，本课是全课程最后一课：从读与测走向提交与合入，并给课程收束。发布那一面的版本、分支与报告规范已在开源生态课写过，见 <a href="/llm/eco-release-versioning">发布工程</a>；本课写源码那一面的流程：一个改动从问题到合入经过哪些关卡，以各仓库当时状态为准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一次向活跃框架提交的人，败因几乎不在代码：格式被自动检查打回、改动没有issue归属被问「解决什么」、性能优化没有数据被搁置、动了一个大家都在用的接口被要求先写方案。流程关卡的存在理由是仓库的尺度：每月几十上百个改动、数十个平台与后端组合、无法人工回归——贡献流程就是把上一课的验证协议制度化，把走读得来的上下文变成评审者可以快速核对的证据链。</p><h3 id="关卡链" tabindex="-1">关卡链 <a class="header-anchor" href="#关卡链" aria-label="Permalink to &quot;关卡链&quot;">​</a></h3><p>第一关，问题归属：修 bug 先有可复现报告，加功能先有讨论或方案征集——跨模块的改动（新平台、新注意力后端、调度器行为变化）通常要求先写设计文档再动手，这一步对应走读课定位层次的训练：说清改动落在调度、插座还是账本。第二关，实现与格式：提交前钩子统一格式与类型检查，提交说明写清动机与验证方式，许多仓库要求签署贡献者协议或声明原创。第三关，验证：单元测试覆盖路径，涉及的配置跑兼容矩阵，性能改动必须附上一课协议下的数据。第四关，评审与合入：维护者按模块分工，评审聚焦接口与回归风险；大型重构按弃用周期走，旧接口先警告后移除。</p><p><span class="marginnote">术语翻译：「兼容矩阵」就是把你的改动放到所有官方支持的组合上各跑一遍测试——比如 CUDA 12.1/12.4 × Python 3.10/3.11/3.12 × 有无 FA3，像下棋复盘把每种开局都摆一遍。这些跑在持续集成（CI）机器人上， contributor 本地根本没有那么多机器。</span></p>',8)),(A(),t(o,null,{default:a(()=>[l(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISS%5B%22%E9%97%AE%E9%A2%98%E5%BD%92%E5%B1%9E%EF%BC%9A%E5%8F%AF%E5%A4%8D%E7%8E%B0%E6%8A%A5%E5%91%8A%20%2F%20%E6%96%B9%E6%A1%88%E5%BE%81%E9%9B%86%22%5D%20--%3E%20DESIGN%5B%22%E8%B7%A8%E5%B1%82%E6%94%B9%E5%8A%A8%E5%85%88%E5%86%99%E8%AE%BE%E8%AE%A1%E6%96%87%E6%A1%A3%22%5D%0A%20%20DESIGN%20--%3E%20IMPL%5B%22%E5%AE%9E%E7%8E%B0%EF%BC%9A%E6%A0%BC%E5%BC%8F%E9%92%A9%E5%AD%90%20%2B%20%E7%B1%BB%E5%9E%8B%E6%A3%80%E6%9F%A5%22%5D%0A%20%20IMPL%20--%3E%20TEST%5B%22%E9%AA%8C%E8%AF%81%EF%BC%9A%E5%8D%95%E6%B5%8B%20%2B%20%E5%85%BC%E5%AE%B9%E7%9F%A9%E9%98%B5%20%2B%20%E6%80%A7%E8%83%BD%E6%95%B0%E6%8D%AE%22%5D%0A%20%20TEST%20--%3E%20REV%5B%22%E6%A8%A1%E5%9D%97%E8%AF%84%E5%AE%A1%EF%BC%9A%E6%8E%A5%E5%8F%A3%E4%B8%8E%E5%9B%9E%E5%BD%92%E9%A3%8E%E9%99%A9%22%5D%0A%20%20REV%20--%3E%7C%E8%A6%81%E6%B1%82%E4%BF%AE%E6%94%B9%7C%20IMPL%0A%20%20REV%20--%3E%20MERGE%5B%22%E5%90%88%E5%85%A5%EF%BC%9A%E6%8C%89%E5%BC%83%E7%94%A8%E5%91%A8%E6%9C%9F%E5%8F%91%E5%B8%83%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p><span class="marginnote">性能改动的常见驳回理由不是「没变快」，而是「没有对照」：单次运行、无基线、协议不一致的数据反而减分。上一课的双跑协议在这关是硬通货，附上固定协议与噪声带的数据几乎总能进入技术讨论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把流程读成<strong>证据链的组装</strong>。每个关卡要的证据不同：问题关要复现，方案关要层次定位与备选路线，验证关要测试与数据，评审关要回归风险说明。高效贡献者的做法是先组装证据再写代码：复现脚本和基准协议在动手前就位，改动描述按「什么、为什么、怎么验证」三段写。这也是全课程方法的收口：走读给层次判断，对照课给结构语汇，回归课给验证协议，流程课把这些兑换成合入。反着读也成立：看一个仓库的贡献指南厚不厚、方案征集活不活跃、弃用周期守不守，能反推它的工程成熟度与演进速度。</p><p><span class="marginnote">直觉类比：「证据链」就像法庭上打官司——你不能只喊「我有理」（我的改动是对的），要交物证（复现脚本）、证词（动机说明）、鉴定报告（性能数据）。维护者每周看几十个案子，只采信呈堂证供，不采信口头保证。这也是为什么「先组装证据再写代码」效率高：证据先于立场，评审才快。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>流程的机制根据与之前每课同源：<strong>把稀缺资源从人工搬向自动化</strong>。格式与类型检查交给钩子，兼容矩阵交给持续集成，性能回归交给基准任务与统计阈值；人工评审只留机器判不了的接口设计与取舍。弃用周期是尺度问题的另一面：用户基数大的仓库不能「顺手改接口」，先警告后移除把破坏性变化变成可计划事件。各仓库流程的差异不是官僚程度不同，而是稀缺资源不同——后端组合多的仓库验证关重，研究驱动的仓库方案关轻。</p>',6)),(A(),t(o,null,{default:a(()=>[l(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E4%B8%80%E4%B8%AA%20PR%20%E6%8F%90%E4%BA%A4%E8%BF%9B%E6%9D%A5%22%5D%20--%3E%20BOT%5B%22%E6%9C%BA%E5%99%A8%E5%85%B3%E5%8D%A1%EF%BC%88%E5%87%A0%E5%88%86%E9%92%9F%EF%BC%8C%E6%97%A0%E4%BA%BA%E5%80%BC%E5%AE%88%EF%BC%89%22%5D%0A%20%20BOT%20--%3E%20B1%5B%22%E6%A0%BC%E5%BC%8F%E4%B8%8E%E7%B1%BB%E5%9E%8B%E9%92%A9%E5%AD%90%22%5D%0A%20%20BOT%20--%3E%20B2%5B%22%E5%8D%95%E5%85%83%E6%B5%8B%E8%AF%95%22%5D%0A%20%20BOT%20--%3E%20B3%5B%22%E5%85%BC%E5%AE%B9%E7%9F%A9%E9%98%B5%20CI%22%5D%0A%20%20BOT%20--%3E%20B4%5B%22%E6%80%A7%E8%83%BD%E5%9F%BA%E5%87%86%20vs%20%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20B1%20--%3E%20HUMAN%5B%22%E4%BA%BA%E5%B7%A5%E8%AF%84%E5%AE%A1%EF%BC%88%E7%A8%80%E7%BC%BA%EF%BC%8C%E5%8F%AA%E7%9C%8B%E6%9C%BA%E5%99%A8%E5%88%A4%E4%B8%8D%E4%BA%86%E7%9A%84%EF%BC%89%22%5D%0A%20%20B2%20--%3E%20HUMAN%0A%20%20B3%20--%3E%20HUMAN%0A%20%20B4%20--%3E%20HUMAN%0A%20%20HUMAN%20--%3E%20H1%5B%22%E6%8E%A5%E5%8F%A3%E8%AE%BE%E8%AE%A1%E6%98%AF%E5%90%A6%E5%90%88%E7%90%86%22%5D%0A%20%20HUMAN%20--%3E%20H2%5B%22%E5%9B%9E%E5%BD%92%E9%A3%8E%E9%99%A9%E4%B8%8E%E5%8F%96%E8%88%8D%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">术语翻译：「弃用周期」就是拆迁通知流程——先在旧接口上加一行警告（还能用，但提示新写法），过一两个版本才真正拆掉。直接拆掉会弄坏成千上万下游用户的代码；先警告后移除，把「突然坏」变成「计划内坏」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>流程以各仓库当时状态为准，门槛与工具持续变动，本课只保「归属、证据、验证、评审」的骨架。流程不能替代判断：走读课的方法仍是根，数据结构比目录名耐用，这条从第一课贯穿到此。本课程到此收束：六个走读给了六种把「迭代、插座、账本」兑现成代码的方式，三课对照给了读任何新框架的三问检查单，两课方法给了动手与报数的协议，本课给了让改动落地的路径。带着这套读法去读下一个仓库——版本会变，骨架不变。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贡献流程是证据链组装：问题关要复现，方案关要层次定位，验证关要测试与性能数据，评审关要回归说明。</li><li>先组装证据再写代码；性能数据必须有固定协议与对照，单次无基线的数字反而减分。</li><li>流程的机制是稀缺资源搬向自动化，人工评审只留接口设计与取舍；流程差异反映各仓库稀缺资源不同。</li><li>弃用周期把破坏性变化变成可计划事件；贡献指南的厚度可反推工程成熟度。</li><li>本课程到此收束：六走读、三对照、两方法、一流程；数据结构比目录名耐用，读法跨版本迁移。</li><li>出处：vLLM、SGLang、llama.cpp 等仓库贡献指南与开发者文档，按流程整理。</li></ul>',5))])}const u=i(p,[["render",d]]);export{c as __pageData,u as default};
